                        periodPresets: 'Fechas ya puestas como accesos rápidos (Hoy, Últimos 7 días…). Los días los cuenta el servidor en la zona del negocio; como se traslapan, el servidor manda el total de «Todas». El rango personalizado es el mismo filtro: elegir uno quita el otro.',
                        dateRange: 'Un rango de fechas al final de los accesos rápidos (el chip «Personalizado»). Son dos filtros de texto que viajan como AAAA-MM-DD; el inicio y el fin del día los pone el servidor con la zona del negocio.',
                        dateRangeLimits: 'Los topes del rango, como en el cajón de filtros: el calendario no deja elegir fuera y una fecha tecleada fuera avisa y no deja aplicar o, con limitMode fix, se vuelve el tope. Hoy es el de la zona del producto. Aquí los pedidos no pueden ser futuros.',
