                        fileSize: 'A file’s size (2.4 MB, 74 bytes).',
                        list: 'A list in words (“Ana, Luis and Bruno”).',
                        fallback: 'What is drawn if there is no data (“—” by default).',
                        settings: 'The product’s time zone and currency: said once in ToolkitProvider.',
                        hourCycle: 'The 24-hour clock («15:10», the default) or the 12-hour one with a.m. and p.m. («3:10 p.m.»): said once in ToolkitProvider.',
